# Front sheet: each sleeve is about 10 px inside the first blockout.
for label, side in [("L",1),("R",-1)]:
    for name in ("Sleeve ", "Hand envelope "):
        for v in bpy.data.objects[name+label].data.vertices:
            y = 785-v.co.z/unit
            shift = 10 if y < 360 else max(2,10-(y-360)*.12)
            v.co.x -= side * shift * unit
            if name == "Sleeve " and y >= 330:
                # Outside of the turned cuff sits above the inside.
                v.co.z += (side*v.co.x/unit-114)*.20*unit
for v in bpy.data.objects["Coat envelope with centre opening"].data.vertices:
    if v.co.z/unit < 232:
        v.co.z += (abs(v.co.x/unit)/101*10-5)*unit
view(0)
bpy.ops.wm.save_as_mainfile(filepath=str(ROOT/"cora-blockout.blend"))
